import sys

HEADER = """/*
 * This file is part of Hubbub.
 * Licensed under the MIT License,
 *                http://www.opensource.org/licenses/mit-license.php
 * Copyright 2010 The NetSurf Project.
 *
 * Note: This file is automatically generated by make-entities.py
 *
 * Do not edit file file, changes will be overwritten during build.
 */


"""


class Node:
    __slots__ = ("pivot", "index", "lt", "eq", "gt", "value")

    def __init__(self, pivot, index):
        self.pivot = pivot
        self.index = index
        self.lt = self.eq = self.gt = None
        self.value = None


def insert(nodes, parent, key, code):
    pivot, tail = key[:1], key[1:]
    if parent is None:
        parent = Node(pivot, len(nodes))
        nodes.append(parent)
    if pivot < parent.pivot:
        parent.lt = insert(nodes, parent.lt, key, code)
    elif pivot > parent.pivot:
        parent.gt = insert(nodes, parent.gt, key, code)
    elif pivot == "":
        parent.value = code
    else:
        if tail == "":
            parent.value = code
        parent.eq = insert(nodes, parent.eq, tail, code)
    return parent


def balanced_order(keys):
    if not keys:
        return []
    mid = len(keys) // 2
    return [keys[mid]] + balanced_order(keys[:mid]) + balanced_order(keys[mid + 1:])


def generate(source):
    entities = {}
    with open(source, encoding="utf-8") as f:
        for line in f:
            line = line.rstrip("\n")
            if line.startswith("#") or line == "":
                continue
            elements = line.split()
            entities[elements[0]] = elements[1]

    sys.setrecursionlimit(10000)
    nodes = []
    root = None
    for key in balanced_order(sorted(entities)):
        root = insert(nodes, root, key, entities[key])

    out = [HEADER, "static hubbub_entity_node dict[] = {\n"]
    for node in nodes:
        def ref(n):
            return str(n.index) if n is not None else "-1"
        split = ord(node.pivot) if node.pivot != "" else 0
        out.append("\t{ %d, %s, %s, %s, %s },\n" % (
            split, ref(node.lt), ref(node.eq), ref(node.gt),
            node.value if node.value is not None else "0"))
    out.append("};\n\n")
    out.append("static int32_t dict_root = %d;\n" % root.index)
    return "".join(out)


def write_if_changed(path, text):
    try:
        with open(path, encoding="utf-8") as f:
            if f.read() == text:
                return
    except OSError:
        pass
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)


if __name__ == "__main__":
    source = sys.argv[1] if len(sys.argv) > 1 else "build/Entities"
    target = sys.argv[2] if len(sys.argv) > 2 else "src/tokeniser/entities.inc"
    write_if_changed(target, generate(source))
